const fs = require('fs');
const path = require('path');

const PKM_DIR = '/pkm';
const queryStr = (query || '').trim().toLowerCase();
const LIMIT = 5;

if (!queryStr) return 'No query provided';

const results = [];

function searchDir(dir) {
  if (results.length >= 25) return;
  let entries;
  try { entries = fs.readdirSync(dir, { withFileTypes: true }); }
  catch (e) { return; }
  for (const entry of entries) {
    if (results.length >= 25) break;
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory() && !entry.name.startsWith('.')) {
      searchDir(fullPath);
    } else if (entry.isFile() && entry.name.endsWith('.md')) {
      try {
        const content = fs.readFileSync(fullPath, 'utf8');
        if (content.toLowerCase().includes(queryStr)) {
          const lines = content.split('\n');
          const excerpts = [];
          for (let i = 0; i < lines.length && excerpts.length < 3; i++) {
            if (lines[i].toLowerCase().includes(queryStr)) {
              const start = Math.max(0, i - 1);
              const end = Math.min(lines.length - 1, i + 3);
              excerpts.push(lines.slice(start, end + 1).join('\n').trim());
            }
          }
          results.push({ file: fullPath.replace(PKM_DIR + '/', ''), excerpts });
        }
      } catch (e) {}
    }
  }
}

searchDir(PKM_DIR);

// Rank: filename matches first
results.sort((a, b) => {
  const aF = a.file.toLowerCase().includes(queryStr) ? 0 : 1;
  const bF = b.file.toLowerCase().includes(queryStr) ? 0 : 1;
  return aF - bF;
});

const top = results.slice(0, LIMIT);

if (top.length === 0) return 'No results found for "' + query + '" in PKM';

return 'PKM search results for "' + query + '" (' + results.length + ' total matches, showing ' + top.length + '):\n\n' +
  top.map(r => '## ' + r.file + '\n' + r.excerpts.join('\n---\n')).join('\n\n===\n\n');
